    func testEveryErrorCodeHasItsSentence() {
        L10nRuntime.withLocale(.en) {
            XCTAssertEqual(ApiErrorTable.sentence("unauthorized", items: nil), "Please sign in to continue.")
            XCTAssertEqual(ApiErrorTable.sentence("session_expired", items: nil), "Your session has expired. Please sign in again.")
            XCTAssertEqual(ApiErrorTable.sentence("invalid_credentials", items: nil), "That email address and password do not match an account.")
            XCTAssertEqual(ApiErrorTable.sentence("EMAIL_NOT_VERIFIED", items: nil), "Confirm your email address before signing in.")
            XCTAssertEqual(ApiErrorTable.sentence("no_password", items: nil), "This account signs in with Google or Microsoft and has no password to re-enter. Set a password on the web first.")
            XCTAssertEqual(ApiErrorTable.sentence("NO_PASSWORD_SET", items: nil), "Set a password on this account before changing this setting.")
            XCTAssertEqual(ApiErrorTable.sentence("incorrect_password", items: nil), "That password is not correct.")
            XCTAssertEqual(ApiErrorTable.sentence("token_invalid", items: nil), "That link is no longer valid. Request a new one.")
            XCTAssertEqual(ApiErrorTable.sentence("MFA_REQUIRED", items: nil), "Enter the code from your authenticator app.")
            XCTAssertEqual(ApiErrorTable.sentence("MFA_ENROL_REQUIRED", items: nil), "Set up two-step verification to continue.")
            XCTAssertEqual(ApiErrorTable.sentence("MFA_ALREADY_ENABLED", items: nil), "Two-step verification is already on for this account.")
            XCTAssertEqual(ApiErrorTable.sentence("MFA_NOT_PENDING", items: nil), "There is no second factor waiting to be confirmed.")
            XCTAssertEqual(ApiErrorTable.sentence("MFA_NOT_STARTED", items: nil), "Start setting up two-step verification before confirming it.")
            XCTAssertEqual(ApiErrorTable.sentence("mfa_code_invalid", items: nil), "That code is not valid, or it has already been used.")
            XCTAssertEqual(ApiErrorTable.sentence("browser_session_required", items: nil), "This can only be changed from a browser signed in to this account.")
            XCTAssertEqual(ApiErrorTable.sentence("region_elsewhere", items: nil), "Your account is hosted in another region. Sign in there.")
            XCTAssertEqual(ApiErrorTable.sentence("forbidden", items: nil), "You do not have permission to do that.")
            XCTAssertEqual(ApiErrorTable.sentence("workspace_access_denied", items: nil), "You are not a member of that workspace.")
            XCTAssertEqual(ApiErrorTable.sentence("no_workspace", items: nil), "This account is not a member of any workspace yet.")
            XCTAssertEqual(ApiErrorTable.sentence("member_exists", items: nil), "That email address is already a member of this workspace.")
            XCTAssertEqual(ApiErrorTable.sentence("last_agency_member", items: nil), "This is the last administrator of the workspace, so it cannot be removed or demoted.")
            XCTAssertEqual(ApiErrorTable.sentence("member_not_found", items: nil), "That person is not a member of this workspace.")
            XCTAssertEqual(ApiErrorTable.sentence("security_check_failed", items: nil), "The security check did not pass. Please try again.")
            XCTAssertEqual(ApiErrorTable.sentence("security_check_required", items: nil), "Complete the security check and try again.")
            XCTAssertEqual(ApiErrorTable.sentence("workspace_owner_only", items: nil), "Only the owner of this workspace can do that.")
            XCTAssertEqual(ApiErrorTable.sentence("not_found", items: nil), "We could not find what you asked for.")
            XCTAssertEqual(ApiErrorTable.sentence("workspace_not_found", items: nil), "That workspace could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("workspace_owner_not_found", items: nil), "The owner of that workspace could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("account_not_found", items: nil), "That account could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("call_not_found", items: nil), "That call could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("contact_not_found", items: nil), "That contact could not be found in this workspace.")
            XCTAssertEqual(ApiErrorTable.sentence("message_not_found", items: nil), "That message could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("ticket_not_found", items: nil), "That support request could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("phone_number_not_found", items: nil), "That phone number is not one of this workspace's numbers.")
            XCTAssertEqual(ApiErrorTable.sentence("media_not_found", items: nil), "That file could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("room_not_found", items: nil), "That call room could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("connector_not_found", items: nil), "That connector could not be found.")
            XCTAssertEqual(ApiErrorTable.sentence("mailbox_not_found", items: nil), "No mailbox is connected to this workspace.")
            XCTAssertEqual(ApiErrorTable.sentence("VALIDATION_ERROR", items: nil), "Some of what you entered is not valid. Please check it and try again.")
            XCTAssertEqual(ApiErrorTable.sentence("MISSING_ID", items: nil), "That request was missing something it needed.")
